package io.tenvyr.control.authority;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import java.sql.Connection;
import java.time.Instant;
import java.util.*;
import java.util.function.Function;

/** Activation serializes with claims on the execution row and atomically switches immutable revisions. */
public final class PlanProposalService {
    private final Db db;private final PolicyService policy;private Function<JsonNode,ArrayNode> validator;
    public PlanProposalService(Db db,PolicyService policy){this.db=db;this.policy=policy;}
    public void validator(Function<JsonNode,ArrayNode> validator){this.validator=Objects.requireNonNull(validator);}
    public ObjectNode propose(String execution,JsonNode patch,String source){ObjectNode p=PlanPatchDomain.parse(patch);return db.transaction(t->{lock(t,execution);return insert(t,execution,p,source);});}
    public ObjectNode proposeWithManager(Connection c,String execution,JsonNode patch,String source){ObjectNode p=PlanPatchDomain.parse(patch);Db t=Db.on(c);ObjectNode e=lock(t,execution);ObjectNode active=e.hasNonNull("activePlanRevisionId")?t.one("SELECT * FROM execution_plan_revisions WHERE id=?::uuid",e.get("activePlanRevisionId")):null;if(active==null)throw new IllegalStateException("Execution has no active plan");p.set("baseRevision",active.get("revisionNumber"));return insert(t,execution,p,source);}
    private ObjectNode insert(Db t,String execution,ObjectNode p,String source){ObjectNode max=t.one("SELECT COALESCE(MAX(\"proposalNumber\"),0)+1 n FROM plan_proposals WHERE \"executionId\"=?::uuid",execution);return t.insert("plan_proposals",Json.object("executionId",execution,"proposalNumber",max.get("n"),"baseRevision",p.get("baseRevision"),"proposal",p,"proposalHash",Json.hash(p),"source",source,"status","PENDING"));}
    public ObjectNode activate(String id){return db.transaction(t->activateWithManager(t.connection(),id));}
    public ObjectNode activateWithManager(Connection c,String id){Db t=Db.on(c);ObjectNode p=t.one("SELECT * FROM plan_proposals WHERE id=?::uuid",id);if(p==null)throw new IllegalArgumentException("Plan proposal does not exist");if(!"PENDING".equals(Json.text(p,"status")))return outcome(p);ObjectNode e=t.one("SELECT * FROM executions WHERE id=?::uuid FOR UPDATE",p.get("executionId"));p=t.one("SELECT * FROM plan_proposals WHERE id=?::uuid",id);if(p==null||!"PENDING".equals(Json.text(p,"status")))return p==null?Json.object("decision","STALE","reason","Already decided"):outcome(p);if(e==null||List.of("COMPLETED","FAILED","CANCELLED").contains(Json.text(e,"status")))return decide(t,p,"STALE","Execution cannot activate proposal");ObjectNode active=e.hasNonNull("activePlanRevisionId")?t.one("SELECT * FROM execution_plan_revisions WHERE id=?::uuid",e.get("activePlanRevisionId")):null;if(active==null)return decide(t,p,"STALE","Execution has no readable active revision");if(!active.get("revisionNumber").equals(p.get("baseRevision")))return decide(t,p,"STALE","Base revision is no longer active");Set<String> frozen=new HashSet<>();t.query("SELECT DISTINCT s.\"stepId\" FROM step_executions s JOIN step_attempts a ON a.\"logicalStepId\"=s.id WHERE a.\"executionId\"=?::uuid",p.get("executionId")).forEach(s->frozen.add(Json.text(s,"stepId")));ArrayNode steps;try{if(validator==null)throw new IllegalStateException("Plan validator is not bound");steps=validator.apply(PlanPatchDomain.apply(active.path("plan").path("steps"),frozen,p.get("proposal")));}catch(RuntimeException error){return decide(t,p,"REJECTED","Candidate plan is invalid: "+error.getMessage());}
        if(policy.isConfigured()){ObjectNode action=PolicyDomain.planPatch("plan:"+id,Json.text(p,"executionId"));ObjectNode decision=policy.evaluate(action,c);if("DENY".equals(Json.text(decision,"effect")))return decide(t,p,"REJECTED","Policy DENY: "+Json.stringify(decision.get("reasons")));if("REQUIRE_APPROVAL".equals(Json.text(decision,"effect"))&&!t.exists("SELECT id FROM approval_requests WHERE \"proposalId\"=? AND status='APPROVED'","plan:"+id)){ApprovalService.request(t,action,Instant.now(),3_600_000);return Json.object("decision","PENDING","reason","Awaiting approval before activation");}}
        Map<String,JsonNode> base=new LinkedHashMap<>();Set<String> planners=new HashSet<>();for(JsonNode s:active.path("plan").path("steps")){base.put(Json.text(s,"id"),s);if(Json.bool(s,"planner",false))planners.add(Json.text(s,"id"));}if("planner".equals(Json.text(p,"source")))for(JsonNode s:steps)if(Json.bool(s,"planner",false)&&!planners.contains(Json.text(s,"id")))return decide(t,p,"REJECTED","A planner proposal cannot create planner steps (operator-only)");ObjectNode plan=Json.object("schemaVersion",1,"steps",steps);if(active.path("plan").has("budget"))plan.set("budget",active.path("plan").get("budget"));ArrayNode added=Json.array(),replaced=Json.array();for(JsonNode s:steps){String sid=Json.text(s,"id");if(!base.containsKey(sid))added.add(sid);else if(!Json.hash(s).equals(Json.hash(base.get(sid))))replaced.add(sid);}int number=Json.integer(active,"revisionNumber",1)+1;ObjectNode revision=t.insert("execution_plan_revisions",Json.object("executionId",p.get("executionId"),"revisionNumber",number,"parentRevisionId",active.get("id"),"baseRevision",p.get("baseRevision"),"plan",plan,"planHash",Json.hash(plan),"source",p.get("source"),"reason","Activated PlanPatch proposal "+Json.integer(p,"proposalNumber",0),"validationResult",Json.object("valid",true,"proposalId",p.get("id"),"proposalHash",p.get("proposalHash"),"addedSteps",added,"replacedSteps",replaced)));for(JsonNode s:steps)if(!base.containsKey(Json.text(s,"id")))t.insert("step_executions",Json.object("executionId",p.get("executionId"),"stepId",s.get("id"),"agent",s.get("agent"),"status","PENDING","input",null,"attempt",0,"maxAttempts",1,"frozenSpecHash",null,"frozenAt",null));t.update("executions",Json.text(e,"id"),Json.object("activePlanRevisionId",revision.get("id")));ObjectNode result=decide(t,p,"ACCEPTED","Activated revision "+number+" ("+added.size()+" added, "+replaced.size()+" replaced)");if(!"ACCEPTED".equals(Json.text(result,"decision")))throw new IllegalStateException("Concurrent proposal decision won; activation rolled back");return result;
    }
    private ObjectNode lock(Db t,String id){ObjectNode e=t.one("SELECT * FROM executions WHERE id=?::uuid FOR UPDATE",id);if(e==null)throw new IllegalArgumentException("Execution does not exist");return e;}
    private ObjectNode decide(Db t,ObjectNode p,String decision,String reason){ObjectNode row=t.one("UPDATE plan_proposals SET status=?,\"decisionReason\"=?,\"decidedAt\"=? WHERE id=?::uuid AND status='PENDING' RETURNING *",decision,reason,Instant.now(),p.get("id"));return outcome(row==null?t.one("SELECT * FROM plan_proposals WHERE id=?::uuid",p.get("id")):row);}
    private static ObjectNode outcome(JsonNode p){return Json.object("decision",p.get("status"),"reason",p.hasNonNull("decisionReason")?p.get("decisionReason"):Json.value("Already decided"));}
}
